const produk = $('Cari Produk (Rekap Kode)').first().json;
const sesi = $('Pilih Sesi Aktif (Rekap Kode)').first().json;
const kode = produk['Kode Produk'];
const namaProduk = produk['Nama Produk'] || '-';
const linkMedia = produk['Link Website'] || produk['Link Video'] || produk['Link Foto'] || '-';
const obHarga = produk['Harga Awal (OB)'] || '-';
const kbHarga = produk['Kelipatan BID (KB)'] || '-';

// Ubah link foto Google Drive (jika ada) menjadi direct-link agar bisa dikirim sebagai gambar
let drivePhotoUrl = '';
let linkFoto = produk['Link Foto'] || '';
if (linkFoto.includes('drive.google.com/file/d/')) {
  const match = linkFoto.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (match && match[1]) {
    drivePhotoUrl = 'https://drive.google.com/uc?export=view&id=' + match[1];
  }
} else if (linkFoto) {
  drivePhotoUrl = linkFoto;
}

const rows = $input.all().map(i => i.json);

const mapNama = {};
rows.forEach(r => {
  const noWa = r['penawar_id'];
  const nama = r['penawar_nama'];
  if (noWa && nama && String(nama).trim() !== '') {
    mapNama[noWa] = String(nama).trim();
  }
});

const bidSah = rows.filter(r =>
  String(r['kode_produk']) === String(kode) &&
  (String(r['status_bid_db']).trim() === 'Sah' || String(r['status_bid_db']).trim() === 'Sah (BIN)')
);
bidSah.sort((a, b) => new Date(a['timestamp']) - new Date(b['timestamp']));

// Format sesuai permintaan: nama [nilai bid] - timestamp (tanpa nomor WA)
const bidLines = bidSah.map(r => {
  const nominal = parseInt(r['nominal_akhir']) || 0;
  const noWa = r['penawar_id'] || '-';
  const nama = mapNama[noWa] || r['penawar_nama'] || '-';
  const ts = r['timestamp'] || '-';
  return `${nama} [${nominal}] - ${ts}`;
});

function formatTutup(dateStr) {
  if (!dateStr) return '-';
  const parts = String(dateStr).trim().split(/[- :]/);
  if (parts.length < 5) return String(dateStr);
  const bulanId = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
  const tahun = parts[0];
  const bulan = parseInt(parts[1], 10);
  const tanggal = parts[2];
  const jam = parts[3].padStart(2, '0');
  const menit = parts[4].padStart(2, '0');
  return `Jam ${jam}:${menit} WIB, ${tanggal} ${bulanId[bulan - 1]} ${tahun}`;
}
const closeInfo = formatTutup(sesi['Waktu Selesai']);
const extraTimeInfo = sesi['Extra Time Info'] || 'Extra Time 10 menit berkelanjutan';

const lines = [
  `*ikan ${kode} ${namaProduk}*`,
  `🔥 OB: ${obHarga}rb | KB: ${kbHarga}rb`,
  'Link video ⬇️⬇️⬇️',
  `📸 ${linkMedia}`,
  '',
  `INFO DATA REKAP REALTIME IKAN ${kode} ⬇️`,
  '',
  ...(bidLines.length > 0 ? bidLines : [`*${kode}* : Belum OB`]),
  '-------------------------------',
  '*Close lelang :*',
  `- ${closeInfo}`,
  `- ${extraTimeInfo}`,
  '=========================',
  '_Powered_ by indopetmarket ®'
];

return {
  pesan_rekap_kode: lines.join('\n'),
  drive_photo_url: drivePhotoUrl
};

const pengaturan = $input.item.json;
const now = new Date();

function parseWIB(dateStr) {
    if (!dateStr) return null;
    const parts = String(dateStr).trim().split(/[- :]/);
    if (parts.length < 3) return null;
    const year = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10) - 1;
    const day = parseInt(parts[2], 10);
    const hour = parseInt(parts[3] || '0', 10);
    const minute = parseInt(parts[4] || '0', 10);
    const second = parseInt(parts[5] || '0', 10);
    return new Date(Date.UTC(year, month, day, hour - 7, minute, second));
}

const mulai = parseWIB(pengaturan['Waktu Mulai']);
const selesai = parseWIB(pengaturan['Waktu Selesai']);

const statusOk = pengaturan['Status Lelang'] === 'Berjalan';
const waktuOk = !!(mulai && selesai && now >= mulai && now <= selesai);

let pesan = '';
if (!statusOk) {
    pesan = 'Lelang belum dibuka atau sudah ditutup admin.';
} else if (!waktuOk) {
    pesan = 'Saat ini di luar jam lelang yang dijadwalkan.';
}

return {
    ...pengaturan,
    lelang_aktif: statusOk && waktuOk,
    pesan_tidak_aktif: pesan,
    waktu_sekarang: now
};

const text = $json.text_upper;
const m = text.match(/^BATALKAN TAWAR\s+([0-9]+)$/);
return {
  kode_produk: m ? m[1] : null,
  chat_id: $json.chat_id
};

const kode = $('Parser Batalkan').first().json.kode_produk;
const logs = $input.all().map(i => i.json).filter(r =>
  String(r['kode_produk']) === String(kode) &&
  (r['status_bid_db'] === 'Sah' || r['status_bid_db'] === 'Sah (BIN)'));
logs.sort((a, b) => new Date(b['timestamp']) - new Date(a['timestamp']));

const target = logs[1] || null;

return {
  kode_produk: kode,
  harga_rollback: target ? parseInt(target['nominal_akhir']) : null,
  penawar_rollback_id: target ? target['penawar_id'] : '',
  ada_rollback: !!target
};

const rollback = $('Hitung Rollback').first().json;
const produkAll = $input.all().map(i => i.json);
const produk = produkAll.find(p => String(p['Kode Produk']) === String(rollback.kode_produk));

if (!produk) {
  return [{ json: { error: true, pesan: `Produk ${rollback.kode_produk} tidak ditemukan.` } }];
}

const hargaSebelumBatal = parseInt(produk['Harga Tertinggi Saat Ini']) || 0;
const hargaBaru = rollback.ada_rollback ? rollback.harga_rollback : (parseInt(produk['Harga Awal (OT)']) || 0);
const penawarBaru = rollback.ada_rollback ? rollback.penawar_rollback_id : '';
const jumlahBaru = Math.max((parseInt(produk['Jumlah Bid Masuk']) || 1) - 1, 0);

return [{ json: {
  error: false,
  kode_produk: rollback.kode_produk,
  harga_baru: hargaBaru,
  penawar_baru: penawarBaru,
  jumlah_baru: jumlahBaru,
  harga_sebelum_batal: hargaSebelumBatal
} }];

const text = $json.text_upper;
const m = text.match(/^TAMBAH WAKTU\s+([0-9]+)$/);
return { menit: m ? parseInt(m[1]) : 0, chat_id: $json.chat_id };

const pengaturan = $json;
const menit = $('Parser Tambah Waktu').first().json.menit;

// Hapus '+07:00' agar tidak bergeser mengikuti zona waktu server n8n
const selesaiLama = new Date(String(pengaturan['Waktu Selesai']).replace(' ', 'T'));
selesaiLama.setMinutes(selesaiLama.getMinutes() + menit);

function fmt(d) {
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

return { 
  waktu_selesai_baru: fmt(selesaiLama), 
  menit_tambahan: menit,
  lama: selesaiLama
};

const rows = $input.all().map(i => i.json);
const aktif = rows.find(r => String(r['Status Lelang']).trim() === 'Berjalan');
if (aktif) return [{ json: { ada_sesi_aktif: true, ...aktif }, pairedItem: 0 }];
return [{ json: { ada_sesi_aktif: false, 'Status Lelang': 'Tidak Ada', 'Session ID': null, 'Hari Ke': null, 'Admin IDs': '', 'Grup WA Target': null }, pairedItem: 0 }];

