const aktif = rows.find(r => String(r['Status Lelang']).trim() === 'Berjalan');
if (aktif) return [{ json: { ada_sesi_aktif: true, ...aktif }, pairedItem: 0 }];
return [{ json: { ada_sesi_aktif: false, 'Status Lelang': 'Tidak Ada', 'Session ID': null, 'Hari Ke': null, 'Admin IDs': '', 'Grup WA Target': null }, pairedItem: 0 }];

const text = $json.text_upper;
const m = text.match(/^MULAI PENAWARAN\s+([0-9]+)$/);
return { hari_ke: m ? m[1] : null, chat_id: $json.chat_id };

const hariDiminta = String($('Parser Hari Mulai1').first().json.hari_ke);
const rows = $input.all().map(i => i.json);

// Cari baris lelang sesuai hari yang diminta
const target = rows.find(r => String(r['Hari Ke']).trim() === hariDiminta);

// Cari apakah ada sesi lain yang masih "Berjalan"
const lainAktif = rows.find(r => String(r['Status Lelang']).trim() === 'Berjalan' && String(r['Hari Ke']).trim() !== hariDiminta);

if (!target) {
  return [{ json: { ditemukan: false, hari_diminta: hariDiminta, bentrok: false, kadaluarsa: false }, pairedItem: 0 }];
}

// === LOGIKA PENGECEKAN WAKTU ===
let isKadaluarsa = false;
if (target['Waktu Selesai']) {
    // Format dari sheet "2026-08-18 19:00:00" diubah menjadi format baku "2026-08-18T19:00:00+07:00" (WIB)
    const strWaktuSelesai = String(target['Waktu Selesai']).trim().replace(' ', 'T');
    const endTime = new Date(strWaktuSelesai + '+07:00').getTime();
    const waktuSekarang = new Date().getTime(); // Waktu realtime saat ini

    // Jika waktu saat ini lebih besar dari waktu selesai di sheet, tandai kadaluarsa
    if (waktuSekarang > endTime) {
        isKadaluarsa = true;
    }
}

return [{ json: {
  ditemukan: true,
  bentrok: !!lainAktif,
  hari_lain_aktif: lainAktif ? lainAktif['Hari Ke'] : null,
  kadaluarsa: isKadaluarsa, // Output baru untuk mendeteksi waktu habis
  ...target
}, pairedItem: 0 }];

const cmd = $('Parser Command Media4').first().json;
const rows = $input.all().map(i => i.json);
