}

return { tipe_media, kode_produk, chat_id: $json.chat_id };

const rows = $input.all().map(i => i.json);
const sesi = $('Pilih Sesi Aktif (Rekap)1').first().json;

const hariKe = sesi['Hari Ke'] || '-';
const namaEvent = sesi['Nama Event'] || 'ETJO GUDANGNYA KOI BAGUS 🏎️ [KEEPING CONTEST]';
const kontakAdmin = sesi['Kontak Admin'] || sesi['Admin IDs'] || '-';
const linkWebsite = sesi['Link Website'] || '-';
const extraTimeInfo = sesi['Extra Time Info'] || 'Extra Time 10 menit berkelanjutan';

function formatTutup(dateStr) {
  if (!dateStr) return '-';
  const parts = String(dateStr).trim().split(/[- :]/);
  if (parts.length < 5) return String(dateStr);
  const bulanId = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
  const tahun = parts[0];
  const bulan = parseInt(parts[1], 10);
  const tanggal = parts[2];
  const jam = parts[3].padStart(2, '0');
  const menit = parts[4].padStart(2, '0');
  return `Jam ${jam}:${menit} WIB, ${tanggal} ${bulanId[bulan - 1]} ${tahun}`;
}
const closeInfo = formatTutup(sesi['Waktu Selesai']);

// Ambil SEMUA produk Open di hari ini (bukan hanya yang sudah ada bid),
// supaya kode yang "Belum OB" tetap tampil di rekap.
const semuaProduk = rows
  .filter(p => String(p['Hari Ke']).trim() === String(hariKe).trim() && (p['Status'] || '').trim() === 'Open')
  .sort((a, b) => (parseInt(a['Kode Produk']) || 0) - (parseInt(b['Kode Produk']) || 0));

let itemLines = [];
let totalNilai = 0;
let jumlahTerlelang = 0;
for (const p of semuaProduk) {
  const kode = p['Kode Produk'];
  const jumlahBid = parseInt(p['Jumlah Bid Masuk']) || 0;
  if (jumlahBid > 0) {
    const harga = parseInt(p['Harga Tertinggi Saat Ini']) || 0;
    const penawar = p['Penawar Tertinggi (Nama)'] || '-';
    itemLines.push(`*${kode}* = [${harga}] ${penawar}`);
    totalNilai += harga;
    jumlahTerlelang++;
  } else {
    itemLines.push(`*${kode}* = Belum OB`);
  }
}

const totalRupiah = (totalNilai * 1000).toLocaleString('id-ID');

const lines = [
  '# Rekap Bid Tertinggi Sementara #',
  `*LELANG KE-${hariKe} ${namaEvent}*`,
  '=========================',
  `Admin 📩 wa.me/${kontakAdmin}`,
  `All Foto ➡️ ${linkWebsite}`,
  '-------------------------------',
  ...(itemLines.length > 0 ? itemLines : ['_Belum ada produk berstatus OPEN._']),
  '-------------------------------',
  '*Total :*',
  `- ${jumlahTerlelang} Terlelang Rp ${totalRupiah}`,
  '-------------------------------',
  '*Close lelang :*',
  `- ${closeInfo}`,
  `- ${extraTimeInfo}`,
  '=========================',
  '_Powered by Indopetmarket®_'
];

return { pesan_rekap: lines.join('\n') };

const rows = $input.all().map(i => i.json);
const aktif = rows.find(r => String(r['Status Lelang']).trim() === 'Berjalan');
if (aktif) return [{ json: { ada_sesi_aktif: true, ...aktif }, pairedItem: 0 }];
return [{ json: { ada_sesi_aktif: false, 'Status Lelang': 'Tidak Ada', 'Session ID': null, 'Hari Ke': null }, pairedItem: 0 }];

