const cmd = $('Parser Rekap Kode').first().json;
const sesi = $('Pilih Sesi Aktif (Rekap Kode)').first().json;
const rows = $input.all().map(i => i.json);

// Prioritaskan produk yang 'Hari Ke'-nya sama dengan sesi aktif, fallback ke kode saja
