const rows = $input.all().map(i => i.json);
const sesi = $('Update Pengaturan Set Ditutup').first().json;
const hariKe = sesi['Hari Ke'];

// Hanya mengambil semua produk yang ada di Hari Ke yang bersangkutan tanpa melihat Status
const targetProduk = rows.filter(p => String(p['Hari Ke']).trim() === String(hariKe).trim());

return targetProduk.map(p => ({ json: { kode_produk: p['Kode Produk'] } }));

function parseTanggalFleksibel(raw) {
  if (!raw) return null;
  const str = String(raw).trim();

  // Kasus A: n8n/Google Sheets sudah mengirim ISO date (kolom sempat kebaca sbg tipe Date)
  if (/^\d{4}-\d{2}-\d{2}T/.test(str)) {
    const d = new Date(str);
    if (!isNaN(d.getTime())) return d;
  }

  // Kasus B: format "YYYY-MM-DD HH:mm:ss" (format standar yang diharapkan)
  let m = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) {
    const [, y, mo, d, h, mi, s] = m;
    return new Date(Date.UTC(+y, +mo - 1, +d, +h - 7, +mi, +(s || 0)));
  }

  // Kasus C: format "DD/MM/YYYY HH:mm:ss" (tampilan lokal ID, muncul kalau sel
  // sempat ke-format Google Sheets sebagai Date lalu dibaca sebagai string tampilan)
  m = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) {
    const [, d, mo, y, h, mi, s] = m;
    return new Date(Date.UTC(+y, +mo - 1, +d, +h - 7, +mi, +(s || 0)));
  }

  // Fallback terakhir, biar tidak diam-diam gagal total
  const fallback = new Date(str);
  return isNaN(fallback.getTime()) ? null : fallback;
}

const rows = $input.all().map(item => item.json);
const now = new Date();
const hasil = [];

for (const pengaturan of rows) {
  let harusTutup = false;

  const statusLelang = String(pengaturan['Status Lelang'] || '').trim();
  const isNotified = String(pengaturan['Auto Close Notified'] || '').trim().toUpperCase();

  if (statusLelang === 'Berjalan' && isNotified !== 'TRUE') {
    const selesai = parseTanggalFleksibel(pengaturan['Waktu Selesai']);
    if (selesai && now > selesai) {
      harusTutup = true;
    }
  }

  hasil.push({
    json: {
      ...pengaturan,
      harus_tutup: harusTutup
    }
  });
}

return hasil;

const cmd = $('Parser Command Media4').first().json;
const item = $json;
let linkMedia = '';
let mediaKind = 'text'; // 'image' | 'document' | 'text'

if (cmd.tipe_media === 'FOTO') {
  linkMedia = item['Link Foto'];
  mediaKind = 'image';
} else if (cmd.tipe_media === 'VIDEO') {
  linkMedia = item['Link Video'];
  mediaKind = 'text';
} else if (cmd.tipe_media === 'SERTIFIKAT') {
  linkMedia = item['Link Sertifikat'];
  mediaKind = 'document';
} else if (cmd.tipe_media === 'LINK') {
  linkMedia = item['Link Website'] || item['Link Foto'] || item['Link Video'];
  mediaKind = 'text';
} else {
  linkMedia = item['Link Foto'];
  mediaKind = 'image';
}

let isDrive = false;
let fileId = '';
let finalUrl = linkMedia;

// Google Drive butuh format link yang berbeda tergantung jenis file yang dikirim
if (linkMedia && String(linkMedia).includes('drive.google.com')) {
  isDrive = true;
  const matchId = String(linkMedia).match(/[-\w]{25,}/);
  if (matchId && matchId[0]) {
    fileId = matchId[0];
    if (mediaKind === 'image') {
      finalUrl = 'https://drive.google.com/uc?export=view&id=' + fileId;
    } else if (mediaKind === 'document') {
      finalUrl = 'https://drive.google.com/uc?export=download&id=' + fileId;
    }
  }
}

const nama_produk = item['Nama Produk'] || `Produk ${cmd.kode_produk}`;
const obHarga = item['Harga Awal (OB)'] || '-';
const kbHarga = item['Kelipatan BID (KB)'] || '-';
const jumlahBid = parseInt(item['Jumlah Bid Masuk']) || 0;
const statusBidInfo = jumlahBid > 0
  ? `Harga saat ini: ${item['Harga Tertinggi Saat Ini']}K oleh ${item['Penawar Tertinggi (Nama)'] || '-'}`
  : `Belum OB (Harga awal OB: ${obHarga}rb)`;

const caption = `📌 *${cmd.tipe_media} PRODUK #${cmd.kode_produk}*\n*Nama:* ${nama_produk}\n🔥 OB: ${obHarga}rb | KB: ${kbHarga}rb\n${statusBidInfo}`;
const namaFile = `${cmd.tipe_media}_${cmd.kode_produk}${mediaKind === 'document' ? '.pdf' : ''}`;

if (!linkMedia) {
  mediaKind = 'text';
  finalUrl = 'Data/Link tidak tersedia.';
}

return {
  kode_produk: cmd.kode_produk,
  tipe_media: cmd.tipe_media,
  nama_produk: nama_produk,
  link: finalUrl,
  media_kind: mediaKind,
  is_drive: isDrive,
  file_id: fileId,
  caption: caption,
  filename: namaFile,
  chat_id: cmd.chat_id
};

const produk = $('Cari Produk (Rekap Kode)').first().json;
const sesi = $('Pilih Sesi Aktif (Rekap Kode)').first().json;
const kode = produk['Kode Produk'];
const namaProduk = produk['Nama Produk'] || '-';
const linkMedia = produk['Link Website'] || produk['Link Video'] || produk['Link Foto'] || '-';
const obHarga = produk['Harga Awal (OB)'] || '-';
const kbHarga = produk['Kelipatan BID (KB)'] || '-';

// Ubah link foto Google Drive (jika ada) menjadi direct-link agar bisa dikirim sebagai gambar
let drivePhotoUrl = '';
let linkFoto = produk['Link Foto'] || '';
if (linkFoto.includes('drive.google.com/file/d/')) {
  const match = linkFoto.match(/\/d\/([a-zA-Z0-9_-]+)/);
  if (match && match[1]) {
    drivePhotoUrl = 'https://drive.google.com/uc?export=view&id=' + match[1];
  }
} else if (linkFoto) {
  drivePhotoUrl = linkFoto;
}

const rows = $input.all().map(i => i.json);

const mapNama = {};
rows.forEach(r => {
  const noWa = r['penawar_id'];
  const nama = r['penawar_nama'];
  if (noWa && nama && String(nama).trim() !== '') {
    mapNama[noWa] = String(nama).trim();
  }
