      alasan: `Produk ${kode} berstatus "${produk['Status']}", tidak menerima tawaran.`,
      nominal_akhir: null, harga_sebelumnya: parseInt(produk['Harga Tertinggi Saat Ini']) || 0, is_bin: false });
    continue;
  }

  const hargaAwal = parseInt(produk['Harga Awal (OB)']) || 0;
  const kelipatanDefault = parseInt(produk['Kelipatan BID (KB)']) || 0;
  const hargaSaatIni = parseInt(produk['Harga Tertinggi Saat Ini']) || 0;
  const hargaBIN = parseInt(produk['Harga Tertinggi (BIN)']) || 0;
  const penawarTertinggiId = String(produk['Penawar Tertinggi (No WA)'] || '');
  const jumlahBidMasuk = parseInt(produk['Jumlah Bid Masuk']) || 0;

  let nominalAkhir = 0;
  let is_bin = false;

  if (parser.tipe_bid === 'BIN') {
    if (binDinonaktifkan) {
        hasil.push({ ...base, status_validasi: 'Tidak Sah',
          alasan: `Produk ${kode} sedang memasuki masa EXTRA TIME, fitur BIN dinonaktifkan. Gunakan KB untuk menawar.`,
          nominal_akhir: null, harga_sebelumnya: hargaSaatIni, is_bin: false });
        continue;
    }
    if (hargaBIN <= 0) {
        hasil.push({ ...base, status_validasi: 'Tidak Sah',
          alasan: `Produk ${kode} tidak memiliki opsi BIN.`,
          nominal_akhir: null, harga_sebelumnya: hargaSaatIni, is_bin: false });
        continue;
    }
    if (hargaSaatIni >= hargaBIN) {
        hasil.push({ ...base, status_validasi: 'Tidak Sah',
          alasan: `Produk ${kode} sudah mencapai atau melewati harga BIN.`,
          nominal_akhir: null, harga_sebelumnya: hargaSaatIni, is_bin: false });
        continue;
    }
    nominalAkhir = hargaBIN;
    is_bin = true;
  } else if (parser.tipe_bid === 'OB') {
    // OB hanya boleh dipakai SEKALI untuk membuka bid ikan ini.
    // Setelah ada bid pertama, OB ditolak dan harus pakai KB.
