          alasan: `Produk ${kode} sudah dibuka (OB) oleh ${namaPembuka} di harga ${hargaSaatIni}K. OB hanya berlaku sekali di awal, gunakan KB untuk menawar selanjutnya.`,
          nominal_akhir: null, harga_sebelumnya: hargaSaatIni, is_bin: false });
        continue;
    }
    nominalAkhir = hargaAwal;
  } else if (parser.tipe_bid === 'KB') {
    if (jumlahBidMasuk === 0 && hargaSaatIni === 0) {
        // Belum pernah di-OB sama sekali: KB dianggap OB + KB (sesuai aturan lama)
        nominalAkhir = hargaAwal + kelipatanDefault;
    } else {
        const acuan = hargaSaatIni > 0 ? hargaSaatIni : hargaAwal;
        const kelipatan = (parser.nominal_custom && parser.nominal_custom > 0) ? parser.nominal_custom : kelipatanDefault;
        nominalAkhir = acuan + kelipatan;
    }
  } else {
    nominalAkhir = parser.nominal_custom || 0;
  }

  if (hargaSaatIni > 0 && penawarTertinggiId === parser.penawar_id && !is_bin) {
    hasil.push({ ...base, status_validasi: 'Tidak Sah',
      alasan: `Anda sudah jadi penawar tertinggi di produk ${kode}, tidak bisa menaikkan tawaran sendiri.`,
      nominal_akhir: nominalAkhir, harga_sebelumnya: hargaSaatIni, is_bin: false });
    continue;
  }

  if (hargaSaatIni > 0 && nominalAkhir <= hargaSaatIni && !is_bin) {
    hasil.push({ ...base, status_validasi: 'Tidak Sah',
      alasan: `Penawaran Anda (${nominalAkhir}K) harus lebih tinggi dari harga saat ini (${hargaSaatIni}K) utk produk ${kode}.`,
      nominal_akhir: nominalAkhir, harga_sebelumnya: hargaSaatIni, is_bin: false });
    continue;
  }

  hasil.push({ ...base, status_validasi: 'Sah', alasan: is_bin ? 'BIN diterima.' : 'Penawaran diterima.',
    nominal_akhir: nominalAkhir, harga_sebelumnya: hargaSaatIni,
    jumlah_bid_baru: jumlahBidMasuk + 1,
    is_bin: is_bin, status_bid_db: is_bin ? 'Sah (BIN)' : 'Sah' });
}

