const thresholds = [2, 5, 10, 30, 60]; // menit sebelum mulai, urut dari TERKECIL
const hasil = [];

for (const row of rows) {
  const status = String(row['Status Lelang'] || '').trim().toUpperCase();
  if (status !== 'BELUM MULAI' && status !== 'BELUM DIMULAI' && status !== '') continue;

  // Kalau hitung mundur detik final (10..1) sudah/sedang berjalan untuk baris ini,
  // jangan kirim pengingat menit lagi -- cegah pesan basi muncul setelah sesi mulai.
  const sudahDetikFinal = String(row['Countdown Detik Terkirim Mulai'] || '').trim().toUpperCase();
  if (sudahDetikFinal === 'TRUE') continue;

  const mulai = parseTanggalFleksibel(row['Waktu Mulai']);
  if (!mulai) continue;

  const diffDetikMentah = Math.floor((mulai.getTime() - now.getTime()) / 1000);
  if (diffDetikMentah < 0) continue;
  // Pakai pembulatan ke ATAS (ceil), bukan floor: supaya "5 menit lagi" nempel pas
  // di menit ke-5 sebelum mulai (mis. 21:18 utk mulai 21:23), bukan tampil dari
  // awal menit sebelumnya (21:17) yang terasa "cepat 1 menit".
  const diffMin = Math.ceil(diffDetikMentah / 60);

  const sudahKirim = String(row['Countdown Terkirim'] || '').split(',').map(s => s.trim()).filter(Boolean);
  const checkpoint = thresholds.find(t => diffMin <= t);

  if (checkpoint !== undefined && !sudahKirim.includes(String(checkpoint))) {
    hasil.push({ json: {
      ...row,
      countdown_menit: checkpoint,
      countdown_terkirim_baru: [...sudahKirim, String(checkpoint)].join(',')
    } });
  }
}

return hasil;

