  const diffDetik = Math.floor((selesai.getTime() - now.getTime()) / 1000);
  if (diffDetik < 0) continue; // sudah lewat, biarkan jalur Cek Waktu Habis1 yang menutup

  // --- Deteksi masuk masa EXTRA TIME (sekali per sesi) ---
  // "Ambang Extra Time (menit)" bisa diatur per sesi di sheet Pengaturan (kosong = default 10 menit)
  const statusExtraFitur = String(row['Extra Time Aktif'] ?? '').trim().toUpperCase();
  const extraTimeAktif = !['TIDAK', 'OFF', 'NONAKTIF', 'FALSE'].includes(statusExtraFitur);
  const ambangExtraMenit = parseInt(row['Ambang Extra Time (menit)']) || 10;
  const sudahExtraTime = String(row['Extra Time Notified'] || '').trim().toUpperCase() === 'TRUE';

  if (extraTimeAktif && !sudahExtraTime && diffDetik <= ambangExtraMenit * 60) {
    const jamMatch = String(row['Waktu Selesai'] || '').match(/(\d{1,2}):(\d{2})/);
    const jamSelesai = jamMatch ? `${jamMatch[1].padStart(2, '0')}:${jamMatch[2]}` : '-';
